SELECT AVG(first_score) FROM biz_adjustment_admit
WHERE school_id = #{schoolId}
 AND college_id = #{collegeId} 
 AND major_code = #{majorCode} 
 AND year = #{year}

SELECT school_id, college_id, major_code, year, MIN(first_score) as min_score, MAX(first_score) as max_score, AVG(first_score) as avg_score, COUNT(*) as count FROM biz_adjustment_admit WHERE school_id IN
#{id}
AND year IN
#{y}
GROUP BY school_id, college_id, major_code, year

SELECT
    MIN(first_score) as minScore,
    MAX(first_score) as maxScore,
    AVG(first_score) as avgScore,
    COUNT(*) as count
FROM biz_adjustment_admit
WHERE school_id = #{schoolId}
 AND college_id = #{collegeId} 
 AND major_code = #{majorCode} 
 AND year = #{year}

SELECT first_score
FROM biz_adjustment_admit
WHERE school_id = #{schoolId}
 AND college_id = #{collegeId} 
 AND major_code = #{majorCode} 
 AND year = #{year} 
ORDER BY first_score ASC

SELECT candidate_name, first_score, first_school_name
FROM biz_adjustment_admit
WHERE school_id = #{schoolId}
 AND college_id = #{collegeId} 
 AND major_code = #{majorCode} 
 AND year = #{year} 
ORDER BY first_score DESC
LIMIT 20

SELECT
    a.id AS id,
    a.candidate_name AS candidateName,
    a.first_school_name AS firstSchoolName,
    a.first_score AS firstScore,
    a.retest_score AS retestScore,
    a.total_score AS totalScore
FROM biz_adjustment_admit a


        AND a.school_id = #{reqVO.schoolId}


        AND a.college_id = #{reqVO.collegeId}


        AND a.major_id = #{reqVO.majorId}


        AND a.year = #{reqVO.year}


        AND a.study_mode = #{reqVO.studyMode}


        AND (
            a.candidate_name LIKE CONCAT('%', #{reqVO.keyword}, '%')
            OR a.first_school_name LIKE CONCAT('%', #{reqVO.keyword}, '%')
        )




                AND a.first_school_id = a.school_id


                AND (a.first_school_id IS NULL OR a.first_school_id != a.school_id)




ORDER BY a.total_score DESC, a.first_score DESC, a.id DESC
